-- Comprobación de solo lectura; ejecutar después de 001 y 002.
BEGIN TRANSACTION READ ONLY;
SET LOCAL search_path = pg_catalog, public;
SET LOCAL TIME ZONE 'America/Asuncion';
DO $comprobar$
DECLARE faltantes text; cantidad integer;
BEGIN
    IF current_setting('server_version_num')::integer / 10000 <> 18 THEN
        RAISE EXCEPTION 'Se requiere PostgreSQL 18.';
    END IF;
    IF to_regclass('public.esquema_versiones') IS NULL THEN
        RAISE EXCEPTION 'Falta la estructura. Ejecute 001 y 002 en la base correcta.';
    END IF;
    IF EXISTS (
        SELECT 1 FROM (VALUES ('001','8c43de2fa290cfcf6680810d34479f5f09243004a045312d2e1b938e6a4bbf85'),('002','b5525cbca7af25a7c3ce6bc8aace77ef1e48e2e61fe18af837a7743f22c6a4e5')) esperado(version,checksum)
        LEFT JOIN public.esquema_versiones v USING (version)
        WHERE v.checksum IS DISTINCT FROM esperado.checksum
    ) THEN RAISE EXCEPTION 'Versiones ausentes o checksums diferentes. No edite las migraciones aplicadas.'; END IF;
    SELECT string_agg(nombre, ', ') INTO faltantes FROM unnest(ARRAY['esquema_versiones','usuarios','roles','permisos','usuarios_roles','roles_permisos','categorias','marcas','unidades_medida','clientes','proveedores','metodos_pago','configuracion_comercio','productos','productos_codigos_barras','cajas','cajas_sesiones','ventas','ventas_detalles','pagos','compras','compras_detalles','movimientos_stock','cajas_movimientos','auditoria']) nombre
    WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
                      WHERE n.nspname='public' AND c.relname=nombre AND c.relkind='r');
    IF faltantes IS NOT NULL THEN RAISE EXCEPTION 'Faltan tablas: %', faltantes; END IF;
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_constraint WHERE connamespace='public'::regnamespace AND NOT convalidated) THEN
        RAISE EXCEPTION 'Hay restricciones sin validar.';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indrelid
               WHERE c.relnamespace='public'::regnamespace AND NOT i.indisvalid) THEN
        RAISE EXCEPTION 'Hay índices inválidos.';
    END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.esquema_versiones'::regclass AND contype='p';
    IF cantidad <> 1 THEN RAISE EXCEPTION 'Cantidad de restricciones p inesperada en esquema_versiones.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.esquema_versiones'::regclass AND contype='f';
    IF cantidad <> 0 THEN RAISE EXCEPTION 'Cantidad de restricciones f inesperada en esquema_versiones.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.esquema_versiones'::regclass AND contype='c';
    IF cantidad <> 1 THEN RAISE EXCEPTION 'Cantidad de restricciones c inesperada en esquema_versiones.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.esquema_versiones'::regclass AND contype='u';
    IF cantidad <> 0 THEN RAISE EXCEPTION 'Cantidad de restricciones u inesperada en esquema_versiones.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.usuarios'::regclass AND contype='p';
    IF cantidad <> 1 THEN RAISE EXCEPTION 'Cantidad de restricciones p inesperada en usuarios.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.usuarios'::regclass AND contype='f';
    IF cantidad <> 0 THEN RAISE EXCEPTION 'Cantidad de restricciones f inesperada en usuarios.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.usuarios'::regclass AND contype='c';
    IF cantidad <> (CASE WHEN EXISTS (SELECT 1 FROM public.esquema_versiones WHERE version='004') THEN 5 ELSE 3 END) THEN RAISE EXCEPTION 'Cantidad de restricciones c inesperada en usuarios.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.usuarios'::regclass AND contype='u';
    IF cantidad <> 0 THEN RAISE EXCEPTION 'Cantidad de restricciones u inesperada en usuarios.'; END IF;
