    IF cantidad <> 1 THEN RAISE EXCEPTION 'Cantidad de restricciones u inesperada en cajas_movimientos.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.auditoria'::regclass AND contype='p';
    IF cantidad <> 1 THEN RAISE EXCEPTION 'Cantidad de restricciones p inesperada en auditoria.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.auditoria'::regclass AND contype='f';
    IF cantidad <> 1 THEN RAISE EXCEPTION 'Cantidad de restricciones f inesperada en auditoria.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.auditoria'::regclass AND contype='c';
    IF cantidad <> 3 THEN RAISE EXCEPTION 'Cantidad de restricciones c inesperada en auditoria.'; END IF;
    SELECT count(*) INTO cantidad FROM pg_catalog.pg_constraint WHERE conrelid='public.auditoria'::regclass AND contype='u';
    IF cantidad <> 0 THEN RAISE EXCEPTION 'Cantidad de restricciones u inesperada en auditoria.'; END IF;
    IF EXISTS (SELECT 1 FROM unnest(ARRAY['uq_usuarios_nombre','ix_usuarios_roles_rol','ix_roles_permisos_permiso','uq_categorias_nombre','uq_marcas_nombre','uq_clientes_documento','uq_clientes_generico','ix_clientes_nombre','uq_proveedores_ruc','ix_proveedores_nombre','uq_productos_codigo','ix_productos_descripcion','ix_productos_categoria','ix_productos_marca','ix_productos_unidad','ix_productos_stock_bajo','ix_codigos_barras_producto','uq_caja_sesion_abierta','ix_caja_sesion_apertura_usuario','ix_caja_sesion_cierre_usuario','ix_ventas_fecha','ix_ventas_cliente_fecha','ix_ventas_usuario_fecha','ix_ventas_caja','ix_ventas_detalle_venta','ix_ventas_detalle_producto','ix_pagos_venta','ix_pagos_metodo','uq_compra_documento','ix_compras_fecha','ix_compras_proveedor_fecha','ix_compras_usuario_fecha','ix_compras_detalle_compra','ix_compras_detalle_producto','ix_stock_producto_fecha','ix_stock_usuario','uq_stock_saldo_inicial','ix_caja_movimientos_sesion_fecha','ix_caja_movimientos_usuario','ix_auditoria_usuario_fecha','ix_auditoria_entidad']) nombre WHERE to_regclass('public.' || nombre) IS NULL) THEN RAISE EXCEPTION 'Faltan índices del sistema.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.movimientos_stock'::regclass AND tgname='stock_inmutable' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo stock_inmutable.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.cajas_movimientos'::regclass AND tgname='caja_movimientos_inmutables' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo caja_movimientos_inmutables.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.auditoria'::regclass AND tgname='auditoria_inmutable' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo auditoria_inmutable.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.movimientos_stock'::regclass AND tgname='stock_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo stock_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.productos'::regclass AND tgname='producto_saldo_coherente' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo producto_saldo_coherente.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.movimientos_stock'::regclass AND tgname='movimiento_saldo_coherente' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo movimiento_saldo_coherente.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.ventas'::regclass AND tgname='venta_proteger' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo venta_proteger.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.compras'::regclass AND tgname='compra_proteger' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo compra_proteger.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.ventas_detalles'::regclass AND tgname='venta_detalle_proteger' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo venta_detalle_proteger.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.compras_detalles'::regclass AND tgname='compra_detalle_proteger' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo compra_detalle_proteger.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.pagos'::regclass AND tgname='pago_proteger' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo pago_proteger.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.cajas_movimientos'::regclass AND tgname='caja_movimiento_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo caja_movimiento_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.cajas_sesiones'::regclass AND tgname='caja_sesion_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo caja_sesion_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.ventas'::regclass AND tgname='venta_confirmada_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo venta_confirmada_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.ventas_detalles'::regclass AND tgname='venta_detalle_confirmado_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo venta_detalle_confirmado_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.pagos'::regclass AND tgname='pago_confirmado_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo pago_confirmado_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.compras'::regclass AND tgname='compra_confirmada_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo compra_confirmada_validar.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger WHERE tgrelid='public.compras_detalles'::regclass AND tgname='compra_detalle_confirmado_validar' AND tgenabled IN ('O','A')) THEN RAISE EXCEPTION 'Falta el trigger activo compra_detalle_confirmado_validar.'; END IF;
    SELECT count(*) INTO cantidad FROM public.roles WHERE codigo IN ('ADMINISTRADOR','SUPERVISOR','CAJERO');
    IF cantidad <> 3 THEN RAISE EXCEPTION 'Faltan roles iniciales.'; END IF;
    SELECT count(*) INTO cantidad FROM public.metodos_pago WHERE codigo IN ('EFECTIVO','TARJETA','TRANSFERENCIA','OTROS');
    IF cantidad <> 4 THEN RAISE EXCEPTION 'Faltan métodos de pago.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE es_generico AND activo) THEN RAISE EXCEPTION 'Falta el cliente genérico activo.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.cajas WHERE codigo='CAJA_01') THEN RAISE EXCEPTION 'Falta la caja inicial.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.configuracion_comercio WHERE id=1 AND zona_horaria='America/Asuncion') THEN RAISE EXCEPTION 'Falta la configuración horaria.'; END IF;
    IF EXISTS (SELECT 1 FROM public.productos p WHERE p.stock_actual <> coalesce((SELECT sum(CASE WHEN m.tipo IN ('SALIDA_VENTA','AJUSTE_SALIDA') THEN -m.cantidad ELSE m.cantidad END) FROM public.movimientos_stock m WHERE m.producto_id=p.id),0)) THEN
        RAISE EXCEPTION 'Hay productos con stock diferente de sus movimientos.';
    END IF;
    RAISE NOTICE 'Estructura y datos iniciales verificados correctamente.';
END $comprobar$;
SELECT 'OK' AS estado, current_database() AS base_datos,
       current_setting('server_version') AS version_postgresql,
       (SELECT count(*) FROM information_schema.tables WHERE table_schema='public' AND table_name=ANY(ARRAY['esquema_versiones','usuarios','roles','permisos','usuarios_roles','roles_permisos','categorias','marcas','unidades_medida','clientes','proveedores','metodos_pago','configuracion_comercio','productos','productos_codigos_barras','cajas','cajas_sesiones','ventas','ventas_detalles','pagos','compras','compras_detalles','movimientos_stock','cajas_movimientos','auditoria'])) AS tablas_sistema,
       (SELECT count(*) FROM public.roles) AS roles,
       (SELECT count(*) FROM public.permisos) AS permisos,
       (SELECT count(*) FROM public.metodos_pago) AS metodos_pago,
       (SELECT zona_horaria FROM public.configuracion_comercio WHERE id=1) AS zona_horaria;
COMMIT;
